-- ============================================================================
-- V26 - The full reference-data catalogue, as confirmed by the business.
--
-- V16 seeded only the codes that appeared in the Sprint 3 acceptance criteria,
-- and said so at the time: "PROVISIONAL ... Extend via a follow-up migration
-- once the business confirms; do not edit this file after it has been applied."
-- This is that follow-up. V16 and V18 are untouched, so no checksum changes.
--
--     DISCIPLINE    3 -> 10
--     DESIGN_TYPE   2 -> 17
--     SUBJECT       1 -> 19
--     FLOOR         2 -> 15 active
--     STAGE         6 ->  9 active
--
-- Written as an UPSERT on uq_lookup_type_code, so this is declarative rather
-- than incremental: it states what the catalogue should contain, updates the
-- rows V16 already created instead of duplicating them, and re-running it is a
-- no-op. Verified by applying it twice over a V1-V25 database: zero duplicate
-- (lookup_type, code) pairs, no error on the second run.
--
-- sort_order follows the order the business supplied, because that is the order
-- the dropdowns should render in.
--
-- NOT HERE, and deliberately:
--   * "Any / Applies to all" is not a catalogue row. ChecklistDto.AppliesTo
--     already treats an EMPTY list as Any; seeding an ANY row would create a
--     second, conflicting way to say the same thing.
--   * Sheet size (A0-A4) is a free-text column, not a catalogue. Making it one
--     needs LookupType and ck_lookup_type changed, which is a code change.
--   * Work progress is a Java enum plus ck_design_work_progress. The confirmed
--     list adds three states and drops COMPLETED, so it needs its own migration
--     and a decision about existing COMPLETED rows.
-- ============================================================================

ON CONFLICT (lookup_type, code) DO UPDATE
    SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
        is_active = TRUE, updated_date = NOW(), updated_by = 1;

ON CONFLICT (lookup_type, code) DO UPDATE
    SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
        is_active = TRUE, updated_date = NOW(), updated_by = 1;

ON CONFLICT (lookup_type, code) DO UPDATE
    SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
        is_active = TRUE, updated_date = NOW(), updated_by = 1;

-- 'XX' is here because the confirmed list asks for it, but note the clash:
-- DesignNumberGenerator emits XX as the placeholder for an omitted segment, so
-- a Design whose Floor is genuinely XX and one whose Floor was left blank
-- generate identical Design Numbers. Worth confirming that is intended.
ON CONFLICT (lookup_type, code) DO UPDATE
    SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
        is_active = TRUE, updated_date = NOW(), updated_by = 1;

ON CONFLICT (lookup_type, code) DO UPDATE
    SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
        is_active = TRUE, updated_date = NOW(), updated_by = 1;

-- ── Retire the codes the confirmed list drops ───────────────────────────────
-- Deactivated rather than deleted. Existing Designs reference these by FK and
-- embed the code in their Design Number, so a delete would either violate the
-- constraint or orphan history. Inactive means "cannot be chosen from now on",
-- which is the actual intent, and it reverses with a single UPDATE.
--
--   STAGE 'CON' (Concept) - came from the V14 comment, absent from the list
--   FLOOR 'L01'           - superseded by '01'
UPDATE lookup_value SET is_active = FALSE, updated_date = NOW(), updated_by = 1
WHERE (lookup_type = 'STAGE' AND code = 'CON')
   OR (lookup_type = 'FLOOR' AND code = 'L01');
